(function initCGASBackgroundActionToggle() {
    'use strict';

    const TOGGLE_MESSAGE = { type: 'CGAS_ACTION_TOGGLE_WIDGET' };
    const SCRIPT_FILES = ['content-autosend.js', 'donate-mini.js'];
    const CSS_FILE = 'autosend-style.css';

    const REFRESH_AFTER_RELOAD_KEY = 'cgas.refreshAfterReload';
    const LOADED_VERSION_KEY = 'cgas.loadedManifestVersion';
    const CURRENT_VERSION = chrome.runtime.getManifest().version;
    const SUPPORTED_CHATGPT_URLS = ['https://chatgpt.com/*', 'https://chat.openai.com/*', 'https://claude.ai/*', 'https://www.claude.ai/*'];

    async function refreshChatGPTTabsAfterReload() {
        let tabs = [];
        try {
            tabs = await chrome.tabs.query({ url: SUPPORTED_CHATGPT_URLS });
        } catch (error) {
            log('tabs query failed after runtime reload.', error && error.message ? error.message : String(error));
            return;
        }

        for (const tab of tabs) {
            if (!tab || !tab.id) continue;
            try {
                await chrome.tabs.reload(tab.id);
            } catch (error) {
                log('ChatGPT tab reload failed after runtime reload.', error && error.message ? error.message : String(error));
            }
        }
    }

    function consumeRefreshAfterReloadFlag() {
        setTimeout(() => {
            try {
                chrome.storage.local.get([REFRESH_AFTER_RELOAD_KEY], (data) => {
                    if (!data || !data[REFRESH_AFTER_RELOAD_KEY]) return;
                    chrome.storage.local.remove([REFRESH_AFTER_RELOAD_KEY], () => refreshChatGPTTabsAfterReload());
                });
            } catch (error) {
                log('refresh-after-reload handler crashed.', error && error.message ? error.message : String(error));
            }
        }, 500);
    }

    function refreshTabsWhenManifestVersionChanges() {
        setTimeout(() => {
            try {
                chrome.storage.local.get([LOADED_VERSION_KEY], (data) => {
                    const previous = data && data[LOADED_VERSION_KEY] ? String(data[LOADED_VERSION_KEY]) : '';
                    if (previous === CURRENT_VERSION) return;
                    chrome.storage.local.set({ [LOADED_VERSION_KEY]: CURRENT_VERSION }, () => {
                        refreshChatGPTTabsAfterReload();
                    });
                });
            } catch (error) {
                log('version-change tab refresh failed.', error && error.message ? error.message : String(error));
            }
        }, 650);
    }

    function executeRuntimeReload() {
        setTimeout(() => {
            try {
                chrome.runtime.reload();
            } catch (error) {
                log('chrome.runtime.reload failed.', error && error.message ? error.message : String(error));
            }
        }, 150);
    }

    function log(message, detail) {
        if (detail) {
            console.log('[CGAS Mini BG] ' + message, detail);
            return;
        }
        console.log('[CGAS Mini BG] ' + message);
    }

    function sendToggle(tabId) {
        return new Promise((resolve) => {
            try {
                chrome.tabs.sendMessage(tabId, TOGGLE_MESSAGE, (response) => {
                    const runtimeError = chrome.runtime.lastError;
                    if (runtimeError) {
                        resolve({ ok: false, error: runtimeError.message || String(runtimeError) });
                        return;
                    }
                    if (!response || !response.ok) {
                        resolve({ ok: false, error: response && response.error ? response.error : 'empty or non-ok response' });
                        return;
                    }
                    resolve({ ok: true, response });
                });
            } catch (error) {
                resolve({ ok: false, error: error && error.message ? error.message : String(error) });
            }
        });
    }

    function insertCss(tabId) {
        return new Promise((resolve) => {
            if (!chrome.scripting || typeof chrome.scripting.insertCSS !== 'function') {
                resolve({ ok: false, error: 'chrome.scripting.insertCSS unavailable' });
                return;
            }
            chrome.scripting.insertCSS({ target: { tabId }, files: [CSS_FILE] }, () => {
                const runtimeError = chrome.runtime.lastError;
                if (runtimeError) {
                    resolve({ ok: false, error: runtimeError.message || String(runtimeError) });
                    return;
                }
                resolve({ ok: true });
            });
        });
    }

    function executeContentScript(tabId) {
        return new Promise((resolve) => {
            if (!chrome.scripting || typeof chrome.scripting.executeScript !== 'function') {
                resolve({ ok: false, error: 'chrome.scripting.executeScript unavailable' });
                return;
            }
            chrome.scripting.executeScript({ target: { tabId }, files: SCRIPT_FILES }, () => {
                const runtimeError = chrome.runtime.lastError;
                if (runtimeError) {
                    resolve({ ok: false, error: runtimeError.message || String(runtimeError) });
                    return;
                }
                resolve({ ok: true });
            });
        });
    }

    function installConversationNetworkHook(tabId) {
        return new Promise((resolve) => {
            if (!chrome.scripting || typeof chrome.scripting.executeScript !== 'function') {
                resolve({ ok: false, error: 'chrome.scripting.executeScript unavailable' });
                return;
            }
            chrome.scripting.executeScript({
                target: { tabId },
                world: 'MAIN',
                func: () => {
                    if (window.__NOXOZ_CGAS_CONVERSATION_FETCH_HOOK__) return;
                    window.__NOXOZ_CGAS_CONVERSATION_FETCH_HOOK__ = true;
                    const nativeFetch = window.fetch;
                    if (typeof nativeFetch !== 'function') return;

                    const emit = (phase) => {
                        try {
                            document.dispatchEvent(new CustomEvent('cgas-chatgpt-conversation-network', {
                                detail: { phase, at: Date.now() }
                            }));
                        } catch (error) {
                            // Never interfere with ChatGPT because of diagnostics.
                        }
                    };

                    window.fetch = async function noxozConversationAwareFetch(input, init) {
                        let tracked = false;
                        try {
                            const rawUrl = typeof input === 'string' || input instanceof URL
                                ? String(input)
                                : input && input.url ? String(input.url) : '';
                            const method = String(init && init.method || input && input.method || 'GET').toUpperCase();
                            tracked = method === 'POST' && new URL(rawUrl, location.href).pathname === '/backend-api/f/conversation';
                        } catch (error) {
                            tracked = false;
                        }

                        if (tracked) emit('start');
                        try {
                            const response = await nativeFetch.apply(this, arguments);
                            if (tracked) {
                                try {
                                    response.clone().text().then(
                                        () => emit('complete'),
                                        () => emit('complete')
                                    );
                                } catch (error) {
                                    // PerformanceResourceTiming in the content script is the fallback.
                                }
                            }
                            return response;
                        } catch (error) {
                            if (tracked) emit('complete');
                            throw error;
                        }
                    };
                }
            }, () => {
                const runtimeError = chrome.runtime.lastError;
                if (runtimeError) {
                    resolve({ ok: false, error: runtimeError.message || String(runtimeError) });
                    return;
                }
                resolve({ ok: true });
            });
        });
    }

    async function ensureContentScriptReady(tabId) {
        await insertCss(tabId);
        const injected = await executeContentScript(tabId);
        if (!injected.ok) {
            return injected;
        }
        await new Promise((resolve) => setTimeout(resolve, 80));
        return { ok: true };
    }

    async function handleActionClick(tab) {
        if (!tab || !tab.id) {
            log('Toolbar click ignored: no active tab id.');
            return;
        }

        const firstTry = await sendToggle(tab.id);
        if (firstTry.ok) {
            log('Widget toggled.');
            return;
        }

        log('No content listener yet; injecting runtime then retrying.', firstTry.error);
        const ready = await ensureContentScriptReady(tab.id);
        if (!ready.ok) {
            log('Runtime injection failed. Open/reload ChatGPT then retry.', ready.error);
            return;
        }

        const secondTry = await sendToggle(tab.id);
        if (secondTry.ok) {
            log('Widget toggled after injection.');
            return;
        }

        log('Toggle still failed after injection.', secondTry.error);
    }

    consumeRefreshAfterReloadFlag();
    refreshTabsWhenManifestVersionChanges();

    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
        if (!message || typeof message !== 'object') return false;

        if (message.type === 'CGAS_EXPORT_DEVELOPER_LOG') {
            const filename = String(message.filename || 'NoXoZ_AI_VoiceControl.log').replace(/[^a-zA-Z0-9_.-]/g, '_');
            const body = String(message.content || '');
            const bytes = new TextEncoder().encode(body);
            let binary = '';
            for (let index = 0; index < bytes.length; index += 8192) {
                binary += String.fromCharCode(...bytes.subarray(index, index + 8192));
            }
            const url = 'data:text/plain;charset=utf-8;base64,' + btoa(binary);
            chrome.downloads.download({url, filename, saveAs: true, conflictAction: 'uniquify'}, (downloadId) => {
                const error = chrome.runtime.lastError;
                sendResponse(error ? {ok:false,error:error.message} : {ok:Boolean(downloadId),downloadId});
            });
            return true;
        }

        if (message.type === 'CGAS_INSTALL_CONVERSATION_NETWORK_HOOK') {
            const tabId = sender && sender.tab && sender.tab.id;
            if (!tabId) {
                sendResponse({ ok: false, error: 'No sender tab id' });
                return false;
            }
            installConversationNetworkHook(tabId)
                .then((result) => sendResponse(result))
                .catch((error) => sendResponse({ ok: false, error: error && error.message ? error.message : String(error) }));
            return true;
        }

        if (message.type === 'CGAS_RELOAD_EXTENSION') {
            sendResponse({ ok: true });
            setTimeout(() => chrome.runtime.reload(), 150);
            return false;
        }

        return false;
    });

    chrome.action.onClicked.addListener((tab) => {
        handleActionClick(tab).catch((error) => {
            log('Toolbar click handler crashed.', error && error.message ? error.message : String(error));
        });
    });
}());
